[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>LearnForge — Build & Sell Online Courses, Coaching, Memberships & More</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --brand-primary: oklch(55% 0.22 265);
      --brand-primary-hover: oklch(50% 0.22 265);
      --brand-accent: oklch(70% 0.16 25);
      --brand-accent-secondary: oklch(75% 0.18 145);
      --text-primary: oklch(15% 0.02 265);
      --text-secondary: oklch(45% 0.02 265);
      --text-muted: oklch(55% 0.01 265);
      --bg-surface: oklch(98% 0.01 265);
      --bg-elevated: oklch(100% 0.00 265);
      --bg-subtle: oklch(96% 0.01 265);
      --border-color: oklch(90% 0.01 265);
      --border-hover: oklch(85% 0.02 265);
      --shadow-sm: 0 1px 2px oklch(0% 0.00 265 / 0.05);
      --shadow-md: 0 4px 12px oklch(0% 0.00 265 / 0.08);
      --shadow-lg: 0 12px 32px oklch(0% 0.00 265 / 0.12);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition-fast: 150ms ease;
      --transition-base: 250ms ease;
      --transition-slow: 400ms ease;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--text-primary);
      background: var(--bg-surface);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Typography */
    h1, h2, h3, h4, h5, h6 {
      font-weight: 700;
      line-height: 1.2;
      color: var(--text-primary);
    }

    h1 { font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 800; }
    h2 { font-size: clamp(2rem, 4vw, 3rem); }
    h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
    h4 { font-size: 1.25rem; }

    .text-gradient {
      background: linear-gradient(135deg, var(--brand-primary), oklch(65% 0.18 285));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* Buttons */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 14px 28px;
      font-size: 1rem;
      font-weight: 600;
      border-radius: var(--radius-md);
      border: none;
      cursor: pointer;
      transition: all var(--transition-base);
      text-decoration: none;
    }

    .btn-primary {
      background: var(--brand-primary);
      color: white;
    }

    .btn-primary:hover {
      background: var(--brand-primary-hover);
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: transparent;
      color: var(--text-primary);
      border: 2px solid var(--border-color);
    }

    .btn-secondary:hover {
      border-color: var(--brand-primary);
      color: var(--brand-primary);
    }

    .btn-accent {
      background: var(--brand-accent);
      color: var(--text-primary);
    }

    .btn-accent:hover {
      filter: brightness(1.05);
      transform: translateY(-2px);
    }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: oklch(100% 0.00 265 / 0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border-color);
      padding: 0 24px;
    }

    .nav-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .nav-logo {
      font-size: 1.5rem;
      font-weight: 800;
      color: var(--text-primary);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav-logo-icon {
      width: 36px;
      height: 36px;
      background: var(--brand-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-weight: 500;
      font-size: 0.95rem;
      transition: color var(--transition-fast);
    }

    .nav-links a:hover {
      color: var(--brand-primary);
    }

    .nav-cta {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .nav-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .mobile-menu {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--bg-elevated);
      padding: 24px;
      z-index: 999;
    }

    .mobile-menu.active {
      display: block;
    }

    .mobile-menu a {
      display: block;
      padding: 16px 0;
      color: var(--text-primary);
      text-decoration: none;
      font-size: 1.25rem;
      font-weight: 600;
      border-bottom: 1px solid var(--border-color);
    }

    /* Hero Section */
    .hero {
      padding: 160px 0 80px;
      background: linear-gradient(180deg, oklch(98% 0.01 265) 0%, oklch(96% 0.015 265) 100%);
    }

    .hero-content {
      text-align: center;
      max-width: 900px;
      margin: 0 auto;
    }

    .hero h1 {
      margin-bottom: 24px;
    }

    .hero-subtitle {
      font-size: 1.25rem;
      color: var(--text-secondary);
      max-width: 700px;
      margin: 0 auto 40px;
      line-height: 1.7;
    }

    .hero-actions {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .hero-tabs {
      display: flex;
      justify-content: center;
      margin-top: 48px;
      gap: 4px;
      background: var(--bg-subtle);
      padding: 4px;
      border-radius: var(--radius-lg);
      width: fit-content;
      margin-left: auto;
      margin-right: auto;
    }

    .hero-tab {
      padding: 12px 24px;
      border: none;
      background: transparent;
      border-radius: var(--radius-md);
      font-size: 0.95rem;
      font-weight: 600;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all var(--transition-base);
    }

    .hero-tab.active {
      background: var(--bg-elevated);
      color: var(--text-primary);
      box-shadow: var(--shadow-sm);
    }

    .hero-preview {
      margin-top: 40px;
      background: var(--bg-elevated);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-lg);
      overflow: hidden;
      display: none;
    }

    .hero-preview.active {
      display: block;
      animation: fadeIn 0.4s ease;
    }

    .hero-preview-img {
      width: 100%;
      max-width: 900px;
      height: auto;
      display: block;
    }

    /* Stats Bar */
    .stats-bar {
      padding: 48px 0;
      background: var(--text-primary);
      color: white;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      text-align: center;
    }

    .stat-item h3 {
      font-size: 3rem;
      font-weight: 800;
      color: white;
      margin-bottom: 8px;
    }

    .stat-item p {
      color: oklch(75% 0.05 265);
      font-size: 1rem;
    }

    /* Products Section */
    .products {
      padding: 100px 0;
    }

    .section-label {
      display: inline-block;
      padding: 6px 14px;
      background: oklch(96% 0.18 265 / 0.15);
      color: var(--brand-primary);
      font-size: 0.875rem;
      font-weight: 600;
      border-radius: 100px;
      margin-bottom: 16px;
    }

    .products-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .products-header h2 {
      margin-bottom: 16px;
    }

    .products-header p {
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto;
    }

    .products-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }

    .product-card {
      background: var(--bg-elevated);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--border-color);
      transition: all var(--transition-base);
      text-decoration: none;
      color: inherit;
    }

    .product-card:hover {
      border-color: var(--brand-primary);
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .product-icon {
      width: 56px;
      height: 56px;
      background: var(--brand-primary);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .product-icon svg {
      width: 28px;
      height: 28px;
      color: white;
    }

    .product-card h4 {
      margin-bottom: 12px;
    }

    .product-card p {
      color: var(--text-secondary);
      font-size: 0.95rem;
    }

    /* Why Choose Us */
    .why-choose {
      padding: 100px 0;
      background: var(--bg-subtle);
    }

    .why-choose-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .why-tabs {
      display: flex;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
      margin-bottom: 40px;
    }

    .why-tab {
      padding: 12px 20px;
      background: var(--bg-elevated);
      border: 2px solid var(--border-color);
      border-radius: var(--radius-md);
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all var(--transition-base);
    }

    .why-tab.active {
      border-color: var(--brand-primary);
      background: var(--brand-primary);
      color: white;
    }

    .why-tab:hover:not(.active) {
      border-color: var(--brand-primary);
      color: var(--brand-primary);
    }

    .why-content {
      background: var(--bg-elevated);
      border-radius: var(--radius-xl);
      padding: 48px;
      box-shadow: var(--shadow-md);
    }

    .why-panel {
      display: none;
    }

    .why-panel.active {
      display: block;
      animation: fadeIn 0.4s ease;
    }

    .why-panel h3 {
      margin-bottom: 24px;
      font-size: 1.75rem;
    }

    .why-features {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }

    .why-feature {
      display: flex;
      gap: 16px;
      align-items: flex-start;
    }

    .why-feature-icon {
      width: 24px;
      height: 24px;
      flex-shrink: 0;
      background: oklch(70% 0.18 145);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-top: 2px;
    }

    .why-feature-icon svg {
      width: 14px;
      height: 14px;
      color: white;
    }

    .why-feature p {
      color: var(--text-secondary);
      font-size: 0.95rem;
    }

    /* Global Scale */
    .global-scale {
      padding: 100px 0;
      text-align: center;
    }

    .global-scale h2 {
      margin-bottom: 16px;
    }

    .global-scale > .container > p {
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto 48px;
    }

    /* Integrations */
    .integrations {
      padding: 80px 0;
      background: var(--bg-subtle);
      text-align: center;
    }

    .integrations h2 {
      margin-bottom: 40px;
    }

    .integrations-grid {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 16px;
      max-width: 900px;
      margin: 0 auto;
    }

    .integration-item {
      background: var(--bg-elevated);
      padding: 16px 24px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 500;
      border: 1px solid var(--border-color);
    }

    .integration-logo {
      width: 32px;
      height: 32px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.75rem;
      font-weight: 700;
    }

    /* Testimonials */
    .testimonials {
      padding: 100px 0;
    }

    .testimonials-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .testimonials-carousel {
      position: relative;
      max-width: 1000px;
      margin: 0 auto;
      overflow: hidden;
    }

    .testimonials-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s ease;
    }

    .testimonial-card {
      flex: 0 0 calc(33.333% - 16px);
      background: var(--bg-elevated);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--border-color);
    }

    .testimonial-quote {
      font-size: 1.125rem;
      font-weight: 600;
      margin-bottom: 16px;
      color: var(--text-primary);
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--brand-primary), oklch(65% 0.18 285));
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-weight: 700;
      font-size: 1.125rem;
    }

    .testimonial-info h5 {
      font-size: 1rem;
      margin-bottom: 2px;
    }

    .testimonial-info p {
      color: var(--text-muted);
      font-size: 0.875rem;
    }

    .testimonial-tag {
      display: inline-block;
      padding: 4px 12px;
      background: oklch(70% 0.18 145 / 0.15);
      color: oklch(50% 0.18 145);
      font-size: 0.75rem;
      font-weight: 600;
      border-radius: 100px;
      margin-top: 16px;
    }

    .carousel-controls {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 2px solid var(--border-color);
      background: var(--bg-elevated);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-base);
    }

    .carousel-btn:hover {
      border-color: var(--brand-primary);
      background: var(--brand-primary);
      color: white;
    }

    .carousel-btn svg {
      width: 20px;
      height: 20px;
    }

    /* Pricing Overview */
    .pricing {
      padding: 100px 0;
      background: var(--bg-subtle);
    }

    .pricing-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .pricing-cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .pricing-card {
      background: var(--bg-elevated);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--border-color);
      text-align: center;
    }

    .pricing-card.featured {
      border-color: var(--brand-primary);
      box-shadow: var(--shadow-lg);
    }

    .pricing-card h4 {
      margin-bottom: 8px;
    }

    .pricing-card .price {
      font-size: 2.5rem;
      font-weight: 800;
      color: var(--text-primary);
      margin: 16px 0;
    }

    .pricing-card .price span {
      font-size: 1rem;
      font-weight: 500;
      color: var(--text-muted);
    }

    .pricing-card .description {
      color: var(--text-secondary);
      font-size: 0.95rem;
      margin-bottom: 24px;
    }

    .pricing-features {
      list-style: none;
      text-align: left;
      margin-bottom: 24px;
    }

    .pricing-features li {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 8px 0;
      font-size: 0.95rem;
      color: var(--text-secondary);
    }

    .pricing-features li::before {
      content: "";
      width: 20px;
      height: 20px;
      background: oklch(70% 0.18 145);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    /* FAQ */
    .faq {
      padding: 100px 0;
    }

    .faq-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .faq-list {
      max-width: 800px;
      margin: 0 auto;
    }

    .faq-item {
      border-bottom: 1px solid var(--border-color);
    }

    .faq-question {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 24px 0;
      background: none;
      border: none;
      text-align: left;
      font-size: 1.125rem;
      font-weight: 600;
      color: var(--text-primary);
      cursor: pointer;
      gap: 16px;
    }

    .faq-icon {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--bg-subtle);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      transition: transform var(--transition-base);
    }

    .faq-item.active .faq-icon {
      transform: rotate(45deg);
      background: var(--brand-primary);
      color: white;
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height var(--transition-base);
    }

    .faq-item.active .faq-answer {
      max-height: 200px;
    }

    .faq-answer p {
      padding: 0 0 24px;
      color: var(--text-secondary);
      line-height: 1.7;
    }

    /* CTA Banner */
    .cta-banner {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--brand-primary), oklch(50% 0.22 285));
      color: white;
      text-align: center;
    }

    .cta-banner h2 {
      color: white;
      margin-bottom: 16px;
    }

    .cta-banner p {
      color: oklch(90% 0.05 265);
      max-width: 600px;
      margin: 0 auto 32px;
      font-size: 1.125rem;
    }

    /* Footer */
    .footer {
      padding: 80px 0 40px;
      background: var(--text-primary);
      color: oklch(75% 0.05 265);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      margin-top: 16px;
      font-size: 0.95rem;
      line-height: 1.7;
    }

    .footer-column h5 {
      color: white;
      font-size: 0.875rem;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 20px;
    }

    .footer-column ul {
      list-style: none;
    }

    .footer-column li {
      margin-bottom: 12px;
    }

    .footer-column a {
      color: oklch(75% 0.05 265);
      text-decoration: none;
      font-size: 0.95rem;
      transition: color var(--transition-fast);
    }

    .footer-column a:hover {
      color: white;
    }

    .footer-bottom {
      border-top: 1px solid oklch(25% 0.02 265);
      padding-top: 32px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a {
      color: oklch(60% 0.02 265);
      text-decoration: none;
      font-size: 0.875rem;
    }

    /* Animations */
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .animate-on-scroll {
      opacity: 0;
      transform: translateY(20px);
      transition: all 0.6s ease;
    }

    .animate-on-scroll.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .nav-links { display: none; }
      .nav-toggle { display: block; }
      .products-grid { grid-template-columns: 1fr; }
      .pricing-cards { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .stats-grid { grid-template-columns: 1fr; gap: 24px; }
      .stat-item h3 { font-size: 2.5rem; }
      .why-tabs { flex-direction: column; align-items: stretch; }
      .why-content { padding: 24px; }
      .testimonial-card { flex: 0 0 100%; }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
    }
  </style>
</head>
<body>
  <!-- Navigation -->
  <nav class="nav">
    <div class="nav-inner">
      <a href="index.html" class="nav-logo">
        <div class="nav-logo-icon">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5">
            <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/>
          </svg>
        </div>
        LearnForge
      </a>
      <ul class="nav-links">
