    const heroTabs = document.querySelectorAll('.hero-tab');
    const creatorPreview = document.getElementById('creator-preview');
    const studentPreview = document.getElementById('student-preview');

    heroTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        heroTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        if (tab.dataset.view === 'creator') {
          creatorPreview.classList.add('active');
          studentPreview.classList.remove('active');
        } else {
          studentPreview.classList.add('active');
          creatorPreview.classList.remove('active');
        }
      });
    });

