        whyTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        whyPanels.forEach(panel => {
          panel.classList.remove('active');
          if (panel.id === 'panel-' + tab.dataset.panel) {
            panel.classList.add('active');
          }
        });
